package fraymus.workspace;
import org.json.*;
import java.util.*;

/** Extends the original checked pose report with actual alternatives and forecast residuals. */
final class CounterfactualReport045 {
    static JSONObject data(Counterfactual045 store,String study,JSONObject actual)throws Exception{
        store.compareActual(study,actual);var s=store.audit(study);var forecast=store.run(study,s.getJSONObject("decision").getString("selectedCandidate"));
        String body=actual.getJSONObject("plan").getJSONArray("orderedTargets").getJSONObject(0).getString("objectId");
        var rows=new JSONArray();for(Object raw:s.getJSONArray("candidates")){var c=(JSONObject)raw;var m=c.optJSONObject("metrics",new JSONObject());rows.put(new JSONArray(List.of(c.getString("id"),c.getString("status"),m.has("nativeTicks")?String.valueOf(m.getInt("nativeTicks")):"—",m.has("effortNs")?String.format(Locale.ROOT,"%.6f",m.getDouble("effortNs")):"—",m.has("maxBystanderDriftM")?String.format(Locale.ROOT,"%.6f",m.getDouble("maxBystanderDriftM")):"—",c.optString("duplicateOf",c.optString("reason","")))));}
        JSONArray fp=points(forecast,body),ap=points(actual,body);double maxT=Math.max(fp.getJSONArray(fp.length()-1).getDouble(0),ap.getJSONArray(ap.length()-1).getDouble(0)),min=Double.POSITIVE_INFINITY,max=Double.NEGATIVE_INFINITY;
        for(var a:List.of(fp,ap))for(Object raw:a){double x=((JSONArray)raw).getDouble(1);min=Math.min(min,x);max=Math.max(max,x);}
        var charts=new JSONObject().put("bodyId",body).put("xUnit","native simulated seconds").put("yUnit","body X position, metres").put("forecast",project(fp,maxT,min,max)).put("actual",project(ap,maxT,min,max)).put("sourceForecast",fp).put("sourceActual",ap);
        var d=new JSONObject().put("version",Counterfactual045.VERSION).put("scope",Counterfactual045.SCOPE).put("studyId",study).put("binding",s.getJSONObject("binding")).put("sourceFrameSha256",s.getString("sourceFrameSha256")).put("codeSha256",s.getString("codeSha256")).put("decision",s.getJSONObject("decision")).put("decisionSha256",s.getString("decisionSha256")).put("policy",s.getJSONObject("policy")).put("candidates",s.getJSONArray("candidates")).put("rows",rows).put("comparison",s.getJSONObject("comparison")).put("charts",charts);
        if(s.has("design053"))d.put("design053",s.getJSONObject("design053"));if(s.has("directFirst055"))d.put("directFirst055",s.getJSONObject("directFirst055"));if(Construction054.is(actual.getJSONObject("definition")))d.put("baseline054",Baseline054.compare(s,actual,store.costs054(study)));return d.put("dataSha256",WorldFrames.hash(d));
    }
    private static JSONArray points(JSONObject run,String body){var out=new JSONArray();for(Object raw:run.getJSONArray("samples")){var s=(JSONObject)raw;out.put(new JSONArray(new double[]{s.getDouble("timeS"),ContactPhysics.dynamic(s.getJSONArray("bodies"),body).getJSONArray("position").getDouble(0)}));}return out;}
    private static JSONArray project(JSONArray points,double time,double min,double max){var out=new JSONArray();for(Object raw:points){var p=(JSONArray)raw;out.put(new JSONArray(new double[]{40+720*p.getDouble(0)/Math.max(.001,time),260-220*(p.getDouble(1)-min)/Math.max(.001,max-min)}));}return out;}
    static JSONArray checks(JSONObject d){var checks=new JSONArray().put(new JSONObject().put("selector","#cf045-status").put("expectText","Forecast and execution verified")).put(new JSONObject().put("selector","#cf045-candidates tbody tr").put("expectCount",d.getJSONArray("rows").length())).put(new JSONObject().put("selector","#cf045-selected").put("expectText",d.getJSONObject("decision").getString("selectedCandidate"))).put(new JSONObject().put("selector","#cf045-head").put("expectText",d.getJSONObject("binding").getString("expectedHash"))).put(new JSONObject().put("selector","#cf045-hash").put("expectText",d.getString("dataSha256"))).put(new JSONObject().put("selector","#cf045-forecast").put("expectCount",1)).put(new JSONObject().put("selector","#cf045-actual").put("expectCount",1));if(d.has("design053"))checks.put(new JSONObject().put("selector","#design053-policy").put("expectText",d.has("directFirst055")?"Verify direct control first; expand only after a failed trial":"Original motion and bridge support checks; then lowest measured effort" )).put(new JSONObject().put("selector","#design053-candidates li").put("expectCount",3));if(d.has("baseline054"))checks.put(new JSONObject().put("selector","#baseline054-result").put("expectText",d.getJSONObject("baseline054").getString("verdict"))).put(new JSONObject().put("selector","#baseline054-table tbody tr").put("expectCount",2));if(d.has("load055"))for(Object raw:d.getJSONObject("load055").getJSONArray("results")){var result=(JSONObject)raw;checks.put(new JSONObject().put("selector","#load055-"+result.getString("caseId")).put("expectText",Load055.label(result)));}return checks;}
    static JSONObject verifyView(JSONObject d,JSONObject view){if(!view.getBoolean("visible")||!view.getJSONObject("data").similar(d)||!view.getJSONArray("rows").similar(d.getJSONArray("rows")))throw new IllegalStateException("Counterfactual source/table view differs from original evidence");double error=0;int count=0;for(String key:List.of("forecast","actual")){JSONArray p=d.getJSONObject("charts").getJSONArray(key),observed=view.getJSONArray(key);if(p.length()!=observed.length())throw new IllegalStateException("Missing forecast/actual chart samples");for(int i=0;i<p.length();i++){if(observed.getJSONArray(i).length()!=2)throw new IllegalStateException("Invalid counterfactual chart point");for(int n=0;n<2;n++){double e=Math.abs(p.getJSONArray(i).getDouble(n)-observed.getJSONArray(i).getDouble(n));if(!Double.isFinite(e))throw new IllegalStateException("Nonfinite chart point");error=Math.max(error,e);}count++;}}if(d.has("load055")){var observed=view.getJSONArray("loads055");var results=d.getJSONObject("load055").getJSONArray("results");if(observed.length()!=results.length())throw new IllegalStateException("Load charts missing");for(int k=0;k<results.length();k++){var original=results.getJSONObject(k).getJSONArray("chart");var chart=observed.getJSONArray(k);double maximum=.001;for(Object row:original)maximum=Math.max(maximum,((JSONArray)row).getDouble(1));if(original.length()!=chart.length())throw new IllegalStateException("Load chart samples missing");for(int i=0;i<original.length();i++){double x=40+720*original.getJSONArray(i).getDouble(0)/6,y=260-220*original.getJSONArray(i).getDouble(1)/maximum;error=Math.max(error,Math.max(Math.abs(x-chart.getJSONArray(i).getDouble(0)),Math.abs(y-chart.getJSONArray(i).getDouble(1))));}}}if(!Double.isFinite(error)||error>.002)throw new IllegalStateException("Rendered forecast/actual/load chart differs");return new JSONObject().put("passed",true).put("dataSha256",d.getString("dataSha256")).put("points",count).put("maxError",error);}
    static JSONObject build(JSONObject actual,JSONObject data,JSONArray attempts){var out=WorldReport.build(actual);out.put("title",(data.has("design053")?"Verified assembly design · ":"Counterfactual world · ")+actual.getJSONObject("definition").getString("title"));var files=out.getJSONObject("files");files.put("index.html",files.getString("index.html").replace("<main>","<main>"+HTML));files.put("counterfactual.json",data.toString());if(data.has("load055"))files.put("original-loads.json",data.getJSONObject("load055Original").toString());var manifest=new JSONArray();for(int i=0;i<attempts.length();i++){String name="forecast-attempt-"+(i+1)+".json";var a=attempts.getJSONObject(i);files.put(name,a.toString());manifest.put(new JSONObject().put("file",name).put("candidate",a.getString("candidate")).put("status",a.getString("status")).put("rawSha256",a.getJSONObject("run").getString("rawSha256")));}files.put("forecast-files.json",manifest.toString());out.getJSONArray("sources").put("counterfactual-decision:"+data.getString("decisionSha256"));return out;}
    private static final String HTML="""
<section id="cf045-section"><section id="load055-section" hidden><h2>Independent load experiments</h2><p id="load055-scope"></p><div id="load055-results"></div><p><a href="original-loads.json" download>All original load attempts and native integration records</a></p></section><section id="baseline054-section" hidden><h2>Comparison with one direct attempt</h2><p id="baseline054-result"></p><p id="baseline054-scope"></p><div class="table"><table id="baseline054-table"><thead><tr><th>Method</th><th>Force ceiling N</th><th>Verified</th><th>Ticks</th><th>Force effort N·s</th><th>Work J</th><th>Trial wall ms</th></tr></thead><tbody></tbody></table></div><p id="baseline054-cost"></p></section><section id="design053-section" hidden><h2>Assembly design · tested alternatives</h2><p id="design053-policy"></p><p>Force profiles keep the same stock and target. Each forecast starts in a separate native world. The chosen design must then pass a fresh execution in the continuing world.</p><ul id="design053-candidates"></ul></section><h2 id="cf045-status">Loading original alternatives…</h2><p>Three declared alternatives begin from the same saved world frame. Failed trials remain visible. Forecasts use the same native solver as execution; this is a deterministic simulation comparison.</p><p>Chosen: <b id="cf045-selected"></b></p><p>Original world head: <span id="cf045-head"></span></p><div class="table"><table id="cf045-candidates"><thead><tr><th>Alternative</th><th>Outcome</th><th>Native ticks</th><th>Effort N·s</th><th>Protected drift m</th><th>Reason / duplicate</th></tr></thead><tbody></tbody></table></div><h3>Predicted versus actual motion</h3><p>Forecast: dashed amber. Actual: solid mint. Overlap means the two original traces agree.</p><svg viewBox="0 0 800 300" aria-label="Predicted and actual body motion"><path d="M40 20V260H760" stroke="#5a786e" fill="none"/><polyline id="cf045-forecast" stroke="#d68d25" stroke-width="5" stroke-dasharray="8 6" fill="none"/><polyline id="cf045-actual" stroke="#237c5b" stroke-width="2" fill="none"/></svg><p id="cf045-residual"></p><p>Evidence hash: <span id="cf045-hash"></span></p><details><summary>Original alternatives and comparison</summary><pre id="cf045-data"></pre></details><p><a href="counterfactual.json" download>Numeric comparison JSON</a> · <a href="forecast-files.json" download>Lossless forecast file manifest</a></p><ul id="cf045-downloads"></ul></section><script>
(async()=>{const d=await(await fetch('counterfactual.json')).json(),$=id=>document.getElementById(id);$('cf045-selected').textContent=d.decision.selectedCandidate;$('cf045-head').textContent=d.binding.expectedHash;$('cf045-hash').textContent=d.dataSha256;for(const row of d.rows){const tr=document.createElement('tr');for(const x of row){const td=document.createElement('td');td.textContent=x;tr.append(td);}$('cf045-candidates').tBodies[0].append(tr);}for(const k of ['forecast','actual'])$('cf045-'+k).setAttribute('points',d.charts[k].map(p=>p.join(',')).join(' '));$('cf045-residual').textContent=d.charts.xUnit+' / '+d.charts.yUnit+' · maximum residual '+d.comparison.maxPositionResidualM.toFixed(8)+'m · '+d.comparison.maxAngleResidualDeg.toFixed(8)+'deg · coverage '+d.comparison.sampleCoverage;$('cf045-data').textContent=JSON.stringify(d,null,2);for(const f of await(await fetch('forecast-files.json')).json()){const li=document.createElement('li'),a=document.createElement('a');a.href=f.file;a.download=f.file;a.textContent=f.candidate+' · '+f.status+' · original compressed trace';li.append(a);$('cf045-downloads').append(li);}if(d.design053){$('design053-section').hidden=false;$('design053-policy').textContent=d.directFirst055?'Verify direct control first; expand only after a failed trial':'Original motion and bridge support checks; then lowest measured effort';for(const c of d.candidates){const li=document.createElement('li'),h=c.hypothesis053,m=c.metrics,v=c.structure053;li.textContent=c.id+' · '+h.forceLimitN+' N ceiling · '+c.status+(v?' · supports '+v.supportContacts+'/2 · stable '+v.passed:'')+(m?.effortNs!==undefined?' · '+m.effortNs.toFixed(3)+' N·s measured effort':'')+' · '+h.objection;$('design053-candidates').append(li);}}if(d.baseline054){const b=d.baseline054;$('baseline054-section').hidden=false;$('baseline054-result').textContent=b.verdict;$('baseline054-scope').textContent=b.scope;for(const r of b.rows){const tr=document.createElement('tr');for(const v of [r.label,r.forceLimitN,r.passed?'passed':'failed',r.nativeTicks,r.forceEffortNs.toFixed(3),r.workJ.toFixed(3),r.trialWallMillis===null?'Not measured':r.trialWallMillis.toFixed(1)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('baseline054-table').tBodies[0].append(tr);}$('baseline054-cost').textContent=b.trialAttempts+' original trial attempts · '+b.allTrialTicks+' trial ticks + selected execution = '+b.comparisonPlusExecutionTicks+' ticks · total force effort '+b.comparisonPlusExecutionEffortNs.toFixed(3)+' N·s. Observed trial wall '+(b.allTrialWallMillis/1000).toFixed(3)+' s'+(b.wallTimeComplete?'':' (incomplete after interruption)').toString()+'. Model and report work are additional.';}if(d.load055){$('load055-section').hidden=false;$('load055-scope').textContent=d.load055.scope;for(const r of d.load055.results){const m=r.metrics,p=document.createElement('p');p.id='load055-'+r.caseId;p.textContent=r.caseId+' · '+(m.stable?'stable':'unstable')+' · displacement '+m.maxBeamDisplacementM.toFixed(4)+' m · tilt '+m.maxBeamTiltDeg.toFixed(3)+' deg · supported '+m.supportedSamples+'/'+m.settledSamples+' samples';$('load055-results').append(p);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 800 300');svg.setAttribute('aria-label',r.caseId+' beam displacement over six seconds');const line=document.createElementNS(svg.namespaceURI,'polyline');line.classList.add('load055-curve');const maximum=Math.max(.001,...r.chart.map(p=>p[1]));line.setAttribute('points',r.chart.map(p=>[40+720*p[0]/6,260-220*p[1]/maximum].join(',')).join(' '));line.setAttribute('stroke',m.stable?'#237c5b':'#bd413c');line.setAttribute('stroke-width','2');line.setAttribute('fill','none');svg.append(line);$('load055-results').append(svg);const scale=document.createElement('p');scale.textContent='Time 0–6 s / beam displacement 0–'+maximum.toFixed(4)+' m. Original native samples; each chart has its own vertical scale.';$('load055-results').append(scale);}}$('cf045-status').textContent=d.comparison.passed?'Forecast and execution verified':'Forecast comparison failed';})().catch(e=>{document.querySelector('#cf045-status').textContent='Counterfactual evidence failed: '+e.message;throw e;});
</script>
""";
}
